        LabeledStatement labeledStatement = (LabeledStatement) node;
        AstNode labeledChild = labeledStatement.getStatement();

        // Create a block if it is not already a block.
        if (!(labeledChild instanceof Block)) {
            Block block = new Block();
            block.addChildToBack(labeledChild);
            labeledStatement.setStatement(block);
            labeledChild = block;
        }

        // Add the instrumentation inside the labeled statement block.
        ExpressionStatement newChild = buildInstrumentationStatement(labeledStatement.getLineno());
        labeledChild.addChildToFront(newChild);
    } else if (node instanceof IfStatement) {
        addInstrumentationBefore(node);
    }
    return true;
